import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { Calendar, Clock, Send, CheckCircle, XCircle, Settings } from 'lucide-react';

const SocialMediaScheduler = ({ blogContent, postingHistory, setPostingHistory }) => {
  const [selectedPlatforms, setSelectedPlatforms] = useState([]);
  const [scheduleDate, setScheduleDate] = useState(new Date().toISOString().split('T')[0]);
  const [scheduleTime, setScheduleTime] = useState('18:00');
  const [tokens, setTokens] = useState({
    facebook: '',
    twitter: '',
    linkedin: 'AQWmFzYC_NIKMAnx9ftq...',
    instagram: ''
  });

  const platforms = [
    { id: 'facebook', name: '📘 Facebook', color: '#1877F2' },
    { id: 'twitter', name: '🐦 Twitter', color: '#1DA1F2' },
    { id: 'linkedin', name: '💼 LinkedIn', color: '#0077B5' },
    { id: 'instagram', name: '📷 Instagram', color: '#E4405F' }
  ];

  const handlePlatformToggle = (platformId) => {
    setSelectedPlatforms(prev => 
      prev.includes(platformId) 
        ? prev.filter(id => id !== platformId)
        : [...prev, platformId]
    );
  };

  const schedulePost = () => {
    if (!blogContent || selectedPlatforms.length === 0) return;

    const newPost = {
      id: Date.now(),
      title: blogContent.title,
      platforms: selectedPlatforms.map(id => platforms.find(p => p.id === id).name),
      scheduledTime: new Date(`${scheduleDate}T${scheduleTime}`),
      status: 'scheduled',
      createdAt: new Date()
    };

    setPostingHistory(prev => [...prev, newPost]);

    // Simulate posting after 2 seconds
    setTimeout(() => {
      const results = selectedPlatforms.map(platformId => ({
        platform: platformId,
        success: platformId !== 'linkedin', // LinkedIn fails for demo
        message: platformId === 'linkedin' ? 'Permission denied' : 'Posted successfully'
      }));

      setPostingHistory(prev => 
        prev.map(post => 
          post.id === newPost.id 
            ? { 
                ...post, 
                status: results.some(r => r.success) ? 'posted' : 'failed',
                results,
                postedAt: new Date()
              }
            : post
        )
      );
    }, 2000);
  };

  return (
    <div className="social-scheduler">
      <motion.div 
        className="card"
        initial={{ opacity: 0, scale: 0.95 }}
        animate={{ opacity: 1, scale: 1 }}
        transition={{ duration: 0.4 }}
      >
        <div className="section-header">
          <Calendar className="section-icon" />
          <h2>Social Media Scheduler</h2>
        </div>

        {!blogContent ? (
          <div className="no-content">
            <p>💡 Generate blog content first to enable social media scheduling!</p>
          </div>
        ) : (
          <>
            <div className="content-preview">
              <h3>📝 Ready to Schedule</h3>
              <div className="preview-card">
                <h4>{blogContent.title}</h4>
                <p>{blogContent.content.substring(0, 150)}...</p>
                <div className="hashtags">
                  {blogContent.hashtags.slice(0, 5).join(' ')}
                </div>
              </div>
            </div>

            <div className="platform-selection">
              <h3>🔗 Select Platforms</h3>
              <div className="platforms-grid">
                {platforms.map(platform => (
                  <motion.div
                    key={platform.id}
                    className={`platform-card ${selectedPlatforms.includes(platform.id) ? 'selected' : ''}`}
                    onClick={() => handlePlatformToggle(platform.id)}
                    whileHover={{ scale: 1.02 }}
                    whileTap={{ scale: 0.98 }}
                  >
                    <div className="platform-header">
                      <span className="platform-name">{platform.name}</span>
                      {selectedPlatforms.includes(platform.id) && (
                        <CheckCircle size={20} className="check-icon" />
                      )}
                    </div>

                    <div className="token-status">
                      {tokens[platform.id] ? (
                        <span className="connected">✅ Connected</span>
                      ) : (
                        <span className="disconnected">❌ Not Connected</span>
                      )}
                    </div>
                  </motion.div>
                ))}
              </div>
            </div>

            <div className="schedule-settings">
              <h3>⏰ Schedule Settings</h3>
              <div className="schedule-grid">
                <div className="form-group">
                  <label>📅 Date</label>
                  <input
                    type="date"
                    className="input-field"
                    value={scheduleDate}
                    onChange={(e) => setScheduleDate(e.target.value)}
                  />
                </div>

                <div className="form-group">
                  <label>🕐 Time</label>
                  <input
                    type="time"
                    className="input-field"
                    value={scheduleTime}
                    onChange={(e) => setScheduleTime(e.target.value)}
                  />
                </div>
              </div>
            </div>

            <div className="action-section">
              <motion.button
                className="button-primary schedule-btn"
                onClick={schedulePost}
                disabled={selectedPlatforms.length === 0}
                whileHover={{ scale: 1.02 }}
                whileTap={{ scale: 0.98 }}
              >
                <Send size={20} />
                Schedule Post ({selectedPlatforms.length} platforms)
              </motion.button>
            </div>
          </>
        )}
      </motion.div>

      <style jsx>{`
        .social-scheduler {
          max-width: 900px;
          margin: 0 auto;
        }

        .section-header {
          display: flex;
          align-items: center;
          gap: 0.75rem;
          margin-bottom: 2rem;
        }

        .section-icon {
          color: #667eea;
        }

        .section-header h2 {
          font-size: 1.75rem;
          font-weight: 600;
          color: #1f2937;
        }

        .no-content {
          text-align: center;
          padding: 3rem;
          color: #6b7280;
          font-size: 1.1rem;
        }

        .content-preview {
          margin-bottom: 2rem;
        }

        .content-preview h3 {
          color: #1f2937;
          margin-bottom: 1rem;
        }

        .preview-card {
          background: #f9fafb;
          border-radius: 12px;
          padding: 1.5rem;
          border-left: 4px solid #667eea;
        }

        .preview-card h4 {
          color: #1f2937;
          margin-bottom: 0.5rem;
        }

        .preview-card p {
          color: #6b7280;
          margin-bottom: 1rem;
        }

        .hashtags {
          color: #667eea;
          font-weight: 500;
        }

        .platform-selection {
          margin-bottom: 2rem;
        }

        .platform-selection h3 {
          color: #1f2937;
          margin-bottom: 1rem;
        }

        .platforms-grid {
          display: grid;
          grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
          gap: 1rem;
        }

        .platform-card {
          background: #f9fafb;
          border: 2px solid #e5e7eb;
          border-radius: 12px;
          padding: 1rem;
          cursor: pointer;
          transition: all 0.3s ease;
        }

        .platform-card:hover {
          border-color: #667eea;
          background: #f0f4ff;
        }

        .platform-card.selected {
          border-color: #667eea;
          background: linear-gradient(135deg, #667eea10, #764ba210);
        }

        .platform-header {
          display: flex;
          justify-content: space-between;
          align-items: center;
          margin-bottom: 0.5rem;
        }

        .platform-name {
          font-weight: 500;
          color: #1f2937;
        }

        .check-icon {
          color: #10b981;
        }

        .token-status {
          font-size: 0.9rem;
        }

        .connected {
          color: #10b981;
        }

        .disconnected {
          color: #ef4444;
        }

        .schedule-settings {
          margin-bottom: 2rem;
        }

        .schedule-settings h3 {
          color: #1f2937;
          margin-bottom: 1rem;
        }

        .schedule-grid {
          display: grid;
          grid-template-columns: 1fr 1fr;
          gap: 1rem;
        }

        .form-group {
          display: flex;
          flex-direction: column;
          gap: 0.5rem;
        }

        .form-group label {
          font-weight: 500;
          color: #374151;
        }

        .action-section {
          display: flex;
          justify-content: center;
        }

        .schedule-btn {
          display: flex;
          align-items: center;
          gap: 0.5rem;
          font-size: 1.1rem;
          padding: 1rem 2rem;
        }

        .schedule-btn:disabled {
          opacity: 0.5;
          cursor: not-allowed;
        }

        @media (max-width: 768px) {
          .platforms-grid {
            grid-template-columns: 1fr;
          }

          .schedule-grid {
            grid-template-columns: 1fr;
          }
        }
      `}</style>
    </div>
  );
};

export default SocialMediaScheduler;
